      const bodyW = bDef.w;
      const heightScale = bDef.id === "korea_univ" ? 1.3 : bDef.id === "kaist_ai" ? 1.15 : 1;
      const bodyH = bDef.z * heightScale;
      const bodyD = bDef.h;
